def suma_pares(n): 
    """ int -> int
        EJ6: Suma de los pares entre 0 y n (recursivo)
        PRE: n>=0
    """
    if n==0: 
        return 0
    elif n%2 == 0: 
        return n + suma_pares(n-2)
    else: 
        return suma_pares(n-1)

