def ultimo_indice(lista, elemento): 
    """
     list, any -> int
	OBJ: Retorna el último índice de x si no aparece, -1
    """
    if lista==[]: 
        return -1
    posicion_en_resto = ultimo_indice(lista[1:], elemento)
    if posicion_en_resto == -1:
        if lista[0] == elemento: 
            return 0
        else: 
            return -1
    else:
        return posicion_en_resto + 1

