def prefijo_comun_rec(prefijo_anterior, lista): 
    """str, list -> str
    OBJ: prefijo común más largo de una lista de palabras.
    Lógica análoga a tu sufijo_comun_rec2, pero leyendo desde el inicio.
    """
    if lista == []:
        return prefijo_anterior
    else:
        prefijo_actual = ''
        i = 0
        terminado = False
        while i < min(len(prefijo_anterior), len(lista[0])) and not terminado:
            a = prefijo_anterior[i]
            b = lista[0][i]
            if a == b:
                prefijo_actual += a
                i += 1
            else:
                terminado = True
        return prefijo_comun_rec(prefijo_actual, lista[1:])

# --- Ejemplo de uso ---
cabeza, *cola = ['ancient', 'anne', 'ant']
print(prefijo_comun_rec(cabeza, cola))   # -> 'an'

C142.solution:
def contar_grupos_desde(lista, i): 
    """ list, int -> int
        OBJ: Recorre recursivamente desde el índice i contando grupos.
        Pre: 0 <= i < len(arr)
    """
    if len(lista) == 0:
        return 0
    elif i == len(lista) - 1:
        # El último elemento siempre cierra un grupo
        return 1
    elif lista[i] == lista[i + 1]:
        # Seguimos dentro del mismo grupo
        return contar_grupos_desde(lista, i + 1)
    else:
        # Cambio de valor: cerramos un grupo y sumamos 1
        return 1 + contar_grupos_desde(lista, i + 1)

#probador
print(contar_grupos_desde([2, 2, 2, 3, 3, 1], 0))

